Method.Source:
/// <summary>
/// Sales/Transfer order number parameter
/// </summary>
/// <param name = "_transferId">transferId</param>
/// <returns>transferId</returns>
[
    DataMemberAttribute("TransferId"),
    SysOperationLabelAttribute(literalStr("@SYS9694")),
    SysOperationControlVisibilityAttribute(false)

]
public InventTransferId parmTransferId(InventTransferId _transferId = transferId)
{
    transferId = _transferId;

    return transferId;
}
